use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm;

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input by contract;
        // we defend it anyway rather than trust the crossing.
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds 512 bytes".to_string(),
            });
        }

        let system = "You are a customer support agent. Answer the user's question \
                      directly. You may ask to call the `lookup` tool to search the \
                      knowledge base; use it only when the answer needs stored facts.";

        let mut prompt = build_prompt(&ctx);

        // Bounded tool-orchestration loop. The only tool interface in this
        // node's world is `kb-read`, so the one request we can honour is a
        // knowledge-base lookup; any other `tool` name is answered with an
        // empty result set rather than reaching for authority we lack.
        for _ in 0..4 {
            match tool_llm::generate(system, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    let results = if is_lookup(&req.tool) {
                        kb_read::lookup(&req.query)
                    } else {
                        Vec::new()
                    };
                    prompt.push_str("\n\n[tool ");
                    prompt.push_str(&req.tool);
                    prompt.push_str(" query=\"");
                    prompt.push_str(&req.query);
                    prompt.push_str("\"]\n");
                    if results.is_empty() {
                        prompt.push_str("(no results)");
                    } else {
                        prompt.push_str(&results.join("\n"));
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge".to_string(),
        })
    }
}

fn is_lookup(tool: &str) -> bool {
    matches!(tool, "lookup" | "kb-read" | "kb" | "knowledge-base")
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut p = String::new();
    p.push_str("intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push_str("\nquestion: ");
    p.push_str(&ctx.question);
    if !ctx.knowledge.is_empty() {
        p.push_str("\nknowledge:\n");
        p.push_str(&ctx.knowledge.join("\n"));
    }
    p
}

fn intent_label(i: Intent) -> &'static str {
    match i {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
